namespace SuperDock.SearchViews;
internal sealed class DocumentPreview:DockPanel{
readonly StackPanel paging=new(){Orientation=Orientation.Horizontal,Visibility=Visibility.Collapsed};readonly ContentControl body=new();readonly TextBlock label=new();string? path,pdf;int page,version;bool original=true;readonly Action<bool> mode;
public DocumentPreview(Action<bool> mode,object? model=null){this.mode=mode;var tools=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,0,10)};var footer=new DockPanel{Margin=new Thickness(0,10,0,0)};DockPanel.SetDock(paging,Dock.Right);footer.Children.Add(paging);footer.Children.Add(label);var buttons=new List<Button>();foreach(var name in new[]{"原始预览","文本预览","上一页","下一页"}){var b=new Button{Content=name=="上一页"?"‹":name=="下一页"?"›":name=="原始预览"?"原始":"文本",ToolTip=name,Padding=new Thickness(12,5,12,5),Margin=new Thickness(1,0,1,0),Foreground=Theme.Text,Background=name=="原始预览"?Theme.Selected:Brushes.Transparent,BorderThickness=new Thickness(0),FontSize=name.Contains("页")?18:12,Cursor=System.Windows.Input.Cursors.Hand};b.Template=(ControlTemplate)System.Windows.Markup.XamlReader.Parse("<ControlTemplate xmlns=\"http://schemas.microsoft.com/winfx/2006/xaml/presentation\" TargetType=\"Button\"><Border x:Name=\"Face\" xmlns:x=\"http://schemas.microsoft.com/winfx/2006/xaml\" CornerRadius=\"6\" Background=\"{TemplateBinding Background}\" Padding=\"{TemplateBinding Padding}\"><ContentPresenter HorizontalAlignment=\"Center\" VerticalAlignment=\"Center\"/></Border><ControlTemplate.Triggers><Trigger Property=\"IsMouseOver\" Value=\"True\"><Setter TargetName=\"Face\" Property=\"Background\" Value=\"{DynamicResource AccentSoftBrush}\"/></Trigger></ControlTemplate.Triggers></ControlTemplate>");buttons.Add(b);b.Click+=async(_,_)=>{if(!name.Contains("页"))foreach(var choice in buttons.Where(x=>x.ToolTip is string title&&!title.Contains("页")))choice.Background=ReferenceEquals(choice,b)?Theme.Selected:Brushes.Transparent;if(name=="文本预览"){original=false;version++;paging.Visibility=Visibility.Collapsed;await RenderText();return;}original=true;mode(true);if(name=="上一页")page=Math.Max(0,page-1);if(name=="下一页")page++;await Render();};if(name.Contains("页"))paging.Children.Add(b);else tools.Children.Add(b);}var capsule=new Border{CornerRadius=new CornerRadius(18),Background=Theme.Card,BorderBrush=Theme.Stroke,BorderThickness=new Thickness(.6),Padding=new Thickness(2),HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,0,0,10),Child=tools};tools.Margin=new Thickness(0);DockPanel.SetDock(capsule,Dock.Top);Children.Add(capsule);DockPanel.SetDock(footer,Dock.Bottom);label.FontSize=11;label.VerticalAlignment=VerticalAlignment.Center;label.TextWrapping=TextWrapping.Wrap;label.Foreground=Theme.Muted;Children.Add(footer);Children.Add(body);}
public async void Select(string? value){path=value;pdf=null;page=0;paging.Visibility=Visibility.Collapsed;version++;if(original)await Render();else await RenderText();}
async Task RenderText(){int request=version;string? selected=path;var text=new TextBox{IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Background=Brushes.Transparent,Foreground=Theme.Text,BorderThickness=new Thickness(0),Padding=new Thickness(8),FontSize=13};if(body.Content is WebBrowser browser)browser.Dispose();body.Content=text;label.Text="正在读取文本…";if(selected==null){label.Text="请选择文件";return;}try{var result=await new SuperDock.Search.FilePreviewService().BuildAsync(selected,CancellationToken.None);if(request!=version||original)return;text.Text=result.Text;label.Text=string.IsNullOrEmpty(result.Text)?result.Hint:"文本预览";}catch(Exception ex){if(request==version)label.Text="文本读取失败："+ex.Message;}}async Task Render(){int request=version;try{if(path==null){body.Content=null;return;}string ext=Path.GetExtension(path).ToLowerInvariant();label.Text="正在生成原始预览…";
if(ext is ".html" or ".htm"){var html=await ReadHtml(path);if(request!=version)return;html=System.Text.RegularExpressions.Regex.Replace(html,@"<(script|iframe|object|embed|link|meta)\b[^>]*>.*?</\1\s*>|<(script|iframe|object|embed|link|meta)\b[^>]*/?>","",System.Text.RegularExpressions.RegexOptions.IgnoreCase|System.Text.RegularExpressions.RegexOptions.Singleline);html=System.Text.RegularExpressions.Regex.Replace(html,@"\s(on\w+|src|href|srcdoc|style)\s*=\s*(""[^""]*""|'[^']*'|[^\s>]+)","",System.Text.RegularExpressions.RegexOptions.IgnoreCase);var browser=new WebBrowser();body.Content=browser;browser.NavigateToString("<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">"+html);label.Text="HTML 原始预览 · 已禁用脚本及外部资源";return;}
if(ext is ".doc" or ".docx" or ".xls" or ".xlsx" or ".ppt" or ".pptx"){pdf??=await ConvertOffice(path);if(request!=version)return;}else pdf=path;
if(Path.GetExtension(pdf).Equals(".pdf",StringComparison.OrdinalIgnoreCase)){var doc=await PdfDocument.LoadFromFileAsync(await StorageFile.GetFileFromPathAsync(pdf));if(request!=version)return;paging.Visibility=Visibility.Visible;page=Math.Clamp(page,0,Math.Max(0,(int)doc.PageCount-1));using var sheet=doc.GetPage((uint)page);using var stream=new InMemoryRandomAccessStream();await sheet.RenderToStreamAsync(stream,new PdfPageRenderOptions{DestinationWidth=1200});using var reader=new DataReader(stream.GetInputStreamAt(0));await reader.LoadAsync((uint)stream.Size);var bytes=new byte[(int)stream.Size];reader.ReadBytes(bytes);if(request!=version)return;var image=new BitmapImage();using var memory=new MemoryStream(bytes);image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=memory;image.EndInit();image.Freeze();body.Content=new ScrollViewer{Content=new Image{Source=image,Stretch=Stretch.Uniform},VerticalScrollBarVisibility=ScrollBarVisibility.Auto};label.Text=$"第 {page+1} / {doc.PageCount} 页";return;}
if(ext is ".png" or ".jpg" or ".jpeg" or ".bmp" or ".gif"){body.Content=new Image{Source=new BitmapImage(new Uri(path)),Stretch=Stretch.Uniform};label.Text="图片预览";return;}body.Content=null;label.Text="此格式暂不支持原始排版，请切换文本预览。";
}catch(Exception ex){if(request==version){body.Content=null;label.Text="原始预览不可用："+ex.Message+"；可切换文本预览。";}}}
internal static async Task<string> ReadHtml(string file){var bytes=await File.ReadAllBytesAsync(file);System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);if(bytes.Length>2&&bytes[0]==255&&bytes[1]==254)return System.Text.Encoding.Unicode.GetString(bytes).TrimStart('\uFEFF');if(bytes.Length>2&&bytes[0]==254&&bytes[1]==255)return System.Text.Encoding.BigEndianUnicode.GetString(bytes).TrimStart('\uFEFF');if(bytes.Length>3&&bytes[0]==239&&bytes[1]==187&&bytes[2]==191)return System.Text.Encoding.UTF8.GetString(bytes).TrimStart('\uFEFF');var header=System.Text.Encoding.ASCII.GetString(bytes,0,Math.Min(4096,bytes.Length));var match=System.Text.RegularExpressions.Regex.Match(header,@"charset\s*=\s*[""']?([\w-]+)",System.Text.RegularExpressions.RegexOptions.IgnoreCase);if(match.Success)try{return System.Text.Encoding.GetEncoding(match.Groups[1].Value).GetString(bytes);}catch{}try{return new System.Text.UTF8Encoding(false,true).GetString(bytes);}catch{return System.Text.Encoding.GetEncoding(936).GetString(bytes);}}static Task<string> ConvertOffice(string source){var tcs=new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);var thread=new Thread(()=>{dynamic? app=null,document=null;try{string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SuperDock","preview-cache");Directory.CreateDirectory(folder);string key=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(source+File.GetLastWriteTimeUtc(source).Ticks)));string output=Path.Combine(folder,key+".pdf");if(File.Exists(output)){tcs.SetResult(output);return;}string ext=Path.GetExtension(source).ToLowerInvariant();string id=ext.StartsWith(".xls")?"Excel.Application":ext.StartsWith(".ppt")?"PowerPoint.Application":"Word.Application";var type=Type.GetTypeFromProgID(id)??throw new InvalidOperationException("未安装兼容的 Microsoft Office 渲染组件");app=Activator.CreateInstance(type)!;try{app.AutomationSecurity=3;}catch{}if(id.StartsWith("Excel")){app.Visible=false;app.DisplayAlerts=false;app.AskToUpdateLinks=false;document=app.Workbooks.Open(source,0,true);document.ExportAsFixedFormat(0,output);}else if(id.StartsWith("PowerPoint")){document=app.Presentations.Open(source,-1,0,0);document.SaveAs(output,32);}else{app.Visible=false;app.DisplayAlerts=0;document=app.Documents.Open(source,ConfirmConversions:false,ReadOnly:true,AddToRecentFiles:false);document.ExportAsFixedFormat(output,17);}tcs.TrySetResult(output);}catch(Exception ex){tcs.TrySetException(ex);}finally{try{if(document!=null)document.Close(false);}catch{}try{if(app!=null)app.Quit();}catch{}}});thread.IsBackground=true;thread.SetApartmentState(ApartmentState.STA);thread.Start();return tcs.Task.WaitAsync(TimeSpan.FromSeconds(30));}
